                    wr, wc = r - dr, c - dc
                    if 0 <= wr < N - 1 and 0 <= wc < N - 1:
                        influencing_windows.append((wr, wc))

            possible_next_states = []

            for wr, wc in influencing_windows:
                window = grid[wr:wr+2, wc:wc+2]

                infected_cells = np.where(window == 1)
                C = len(infected_cells[0])

